<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('reports.view');$pdo=db();
$filename='informe-crm-'.date('Y-m-d').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');$put=static function(array $row)use($out){fputcsv($out,$row,';');};
$put(['SÓCRATES CRM · INFORMES Y ANÁLISIS']);$put(['Generado',date('d/m/Y H:i')]);$put([]);
$put(['RESUMEN']);$put(['Indicador','Cantidad']);$put(['Clientes',(int)$pdo->query('SELECT COUNT(*) FROM clients')->fetchColumn()]);$put(['Contactos',(int)$pdo->query('SELECT COUNT(*) FROM contacts')->fetchColumn()]);$put(['Negocios abiertos',(int)$pdo->query("SELECT COUNT(*) FROM deals WHERE status='open'")->fetchColumn()]);$put(['Leads del mes',(int)$pdo->query("SELECT COUNT(*) FROM lead_submissions WHERE created_at>=DATE_FORMAT(CURDATE(),'%Y-%m-01')")->fetchColumn()]);$put(['Tareas atrasadas',(int)$pdo->query("SELECT COUNT(*) FROM activities WHERE status='pending' AND due_at<NOW()")->fetchColumn()]);$put(['Cotizaciones del mes',(int)$pdo->query("SELECT COUNT(*) FROM quotations WHERE issue_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')")->fetchColumn()]);$put([]);
$put(['PIPELINE POR RESPONSABLE']);$put(['Responsable','Moneda','Negocios','Valor','Pronóstico']);foreach($pdo->query("SELECT COALESCE(u.name,'Sin asignar') owner,d.currency,COUNT(*) deals,SUM(d.amount) amount,SUM(d.amount*d.probability/100) weighted FROM deals d LEFT JOIN users u ON u.id=d.owner_user_id WHERE d.status='open' GROUP BY u.id,d.currency ORDER BY weighted DESC") as$r)$put([$r['owner'],$r['currency'],$r['deals'],$r['amount'],$r['weighted']]);$put([]);
$put(['NEGOCIOS POR PAÍS Y MONEDA']);$put(['País','Moneda','Cantidad','Valor','Ponderado']);foreach($pdo->query("SELECT COALESCE(NULLIF(c.country,''),'Sin país') country,d.currency,COUNT(*) deals,SUM(d.amount) amount,SUM(d.amount*d.probability/100) weighted FROM deals d LEFT JOIN clients c ON c.id=d.client_id WHERE d.status='open' GROUP BY country,d.currency ORDER BY deals DESC") as$r)$put([$r['country'],$r['currency'],$r['deals'],$r['amount'],$r['weighted']]);$put([]);
$put(['INGRESOS ÚLTIMOS 12 MESES']);$put(['Mes','Moneda','Total']);foreach($pdo->query("SELECT DATE_FORMAT(payment_date,'%Y-%m') month,currency,SUM(amount) total FROM payments WHERE payment_date>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY month,currency ORDER BY month") as$r)$put([$r['month'],$r['currency'],$r['total']]);$put([]);
if(db_table_exists('projects')){$put(['PROYECTOS']);$put(['Código','Proyecto','Estado','Salud','Avance %','Vencimiento','Moneda','Presupuesto']);foreach($pdo->query("SELECT code,name,status,health,progress,due_date,currency,budget FROM projects ORDER BY created_at DESC") as$r)$put([$r['code'],$r['name'],$r['status'],$r['health'],$r['progress'],$r['due_date'],$r['currency'],$r['budget']]);$put([]);}
if(db_table_exists('project_risks')){$put(['RIESGOS ACTIVOS']);$put(['Proyecto','Riesgo','Probabilidad','Impacto','Estado','Fecha objetivo']);foreach($pdo->query("SELECT p.name project_name,r.title,r.probability,r.impact,r.status,r.due_date FROM project_risks r JOIN projects p ON p.id=r.project_id WHERE r.status IN ('open','mitigating') ORDER BY (r.probability*r.impact) DESC") as$r)$put([$r['project_name'],$r['title'],$r['probability'],$r['impact'],$r['status'],$r['due_date']]);$put([]);}
$put(['ACTIVIDAD ÚLTIMOS 90 DÍAS']);$put(['Tipo','Estado','Cantidad']);foreach($pdo->query("SELECT activity_type,status,COUNT(*) total FROM activities WHERE created_at>=DATE_SUB(NOW(),INTERVAL 90 DAY) GROUP BY activity_type,status") as$r)$put([$r['activity_type'],$r['status'],$r['total']]);
fclose($out);exit;
